/**
 * Purge Manifest v1.2
 * SSOT for the org-nuke deletion order. All 54 tables are classified here.
 *
 * DO NOT edit this file without also updating:
 *   implementations/admin-page/org-nuke/README.md  (Section 3 + Section 14)
 *   MANIFEST_VERSION below
 *
 * Any new org-scoped table added to src/lib/setup-sql.js MUST be added to
 * this manifest before that table ships to production. Failing to do so will
 * cause check C1 (coverage gap) to block all future org-purge prepare calls.
 *
 * See README Section 3.1 for field definitions.
 */

export const MANIFEST_VERSION = 'v1.2';

/**
 * Tables that are never touched by the purge tool.
 *
 * - 'retain'              : no org_id FK to organizations; cross-tenant or system data.
 * - 'fk_points_to_tombstone' : has org_id/target_org_id FK to organizations; the
 *                              tombstone row (step 14.4) satisfies referential integrity
 *                              so these rows are never orphaned.
 *
 * @type {Map<string, 'retain'|'fk_points_to_tombstone'>}
 */
export const PLATFORM_TABLES = new Map([
  ['profiles',              'retain'],
  ['permission_registry',   'retain'],
  ['admin_data',            'retain'],
  ['email_log',             'retain'],
  ['error_events',          'fk_points_to_tombstone'],
  ['audit_log',             'fk_points_to_tombstone'],
  ['impersonation_sessions','fk_points_to_tombstone'],
]);

/**
 * The ordered purge manifest.
 *
 * Each entry represents one table in the deletion sequence.
 * Phases run in ascending numeric order; within a phase, entries run top-to-bottom.
 *
 * @typedef {Object} ManifestEntry
 * @property {number}  phase        - Execution wave (1–14). Lower numbers run first.
 * @property {string}  step         - Human-readable step id, e.g. '1.1'.
 * @property {string}  table        - Raw (unquoted) table name.
 * @property {string}  pgName       - Name passed to supabase-js `.from()`.
 *                                    Same as `table`; PostgREST handles quoting for
 *                                    mixed-case identifiers internally.
 * @property {string}  schemaQuoted - SQL-safe fully-qualified identifier.
 *                                    Case-sensitive names use double-quotes,
 *                                    e.g. `public."Documents"`.
 * @property {'hard_delete'|'storage_then_delete'|'tombstone'} strategy
 * @property {string}  orgIdColumn  - Column to filter on (`'org_id'` for all tables
 *                                    except `organizations`, where it is `'id'`).
 *
 * @type {ManifestEntry[]}
 */
