// ─── Derived helpers ──────────────────────────────────────────────────────────

/**
 * All manifest entry table names as a Set, including 'organizations'.
 * Used by C1 (coverage gap) and C2 (manifest ghost) checks in drift-check.js.
 */
export const MANIFEST_TABLE_SET = new Set(PURGE_MANIFEST.map(e => e.table));

/**
 * Entries where the phase runner will issue a DELETE (strategy !== 'tombstone').
 * Does NOT include the 'organizations' tombstone entry.
 */
export const DELETABLE_ENTRIES = PURGE_MANIFEST.filter(e => e.strategy !== 'tombstone');

/**
 * The single tombstone entry (organizations row, step 14.4).
 * The execute-phases runner handles this entry as a special UPDATE case.
 */
export const TOMBSTONE_ENTRY = PURGE_MANIFEST.find(e => e.strategy === 'tombstone');

/**
 * Tables whose org_id column has ON DELETE CASCADE from organizations.
 * Used by C3 (FK drift) to flag if expected CASCADE tables have changed.
 */
export const EXPECTED_CASCADE_TABLES = new Set([
  'org_memberships',
  'org_invitations',
  'active_routing',
]);

/**
 * Tables that must NOT acquire ON DELETE CASCADE (retention-class tables).
 * C4 blocks if any of these have CASCADE delete rule in pg_catalog.
 */
export const RETENTION_TABLE_NAMES = [...PLATFORM_TABLES.keys()];
